// AddDependencies declares model dependencies.
func (r *Registry) AddDependencies(modelName string, dependsOn []string) ([]string, error) {
\tr.mu.Lock()
\tdefer r.mu.Unlock()

\tmodel, exists := r.models[modelName]
\tif !exists {
\t\treturn nil, fmt.Errorf("model %q not found", modelName)
\t}

\tfor _, dep := range dependsOn {
\t\tif dep == modelName {
\t\t\treturn nil, fmt.Errorf("model cannot depend on itself")
\t\t}
\t\tif _, exists := r.models[dep]; !exists {
\t\t\treturn nil, fmt.Errorf("model %q not found", dep)
\t\t}
\t}

