\t}
\treturn model.Dependencies, nil
}

// GetDependencies returns direct and transitive dependencies for a model.
func (r *Registry) GetDependencies(modelName string) ([]string, []string, error) {
\tr.mu.RLock()
\tdefer r.mu.RUnlock()

\tif _, exists := r.models[modelName]; !exists {
\t\treturn nil, nil, fmt.Errorf("model %q not found", modelName)
\t}

