\t\tdirect = []string{}
\t}

\ttransitive := r.transitiveDependenciesLocked(modelName)
\tsort.Strings(transitive)
\tif transitive == nil {
\t\ttransitive = []string{}
\t}

\treturn direct, transitive, nil
}

// RemoveDependency removes a direct dependency from a model.
func (r *Registry) RemoveDependency(modelName, dep string) error {
\tr.mu.Lock()
\tdefer r.mu.Unlock()

\tmodel, exists := r.models[modelName]
\tif !exists {
\t\treturn fmt.Errorf("model %q not found", modelName)
\t}

\tdirect := r.dependencies[modelName]
\tidx := -1
\tfor i, d := range direct {
\t\tif d == dep {
\t\t\tidx = i
\t\t\tbreak
\t\t}
